#!/bin/sh
# One palette for the whole desktop. A palette is a file in ../themes; this
# script renders it into the nine places the programs read their colours from,
# then tells the running ones to look again.
#
#   theme.sh list          id<TAB>name, one per palette
#   theme.sh current       id of the saved choice (nord if none or invalid)
#   theme.sh set <id>      save the choice, render, reload
#   theme.sh apply         render the saved choice, reload
#   theme.sh ensure        render only if a generated file is missing or stale; reload
#                          nothing. Hyprland's autostart runs it before waybar,
#                          and Ansible may run it over SSH, so it must work
#                          with no graphical session at all.
#
# WHY GENERATED FILES AND NOT ONE CONFIG PER PROGRAM. Waybar, rofi, dunst,
# alacritty, Hyprland, helix, btop, hyprlock and GTK each have their own colour
# syntax and none can read the others. Each config keeps its layout and imports a small file of colours
# from here, so a tracked config never changes when the theme does. The
# generated files are gitignored: they are machine state, like state/screens.*.
#
# The choice is saved under XDG_STATE_HOME, not in the repo, for the same
# reason: it differs per machine and must not dirty the working tree.
set -eu

# Not resolved through symlinks on purpose: stow links this script into
# ~/.config/hypr/scripts, and ../themes is next to it there as well.
hypr_dir=$(cd "$(dirname "$0")/.." && pwd)
themes_dir="$hypr_dir/themes"

config_home="${XDG_CONFIG_HOME:-$HOME/.config}"
data_home="${XDG_DATA_HOME:-$HOME/.local/share}"
state_home="${XDG_STATE_HOME:-$HOME/.local/state}"

choice_file="$state_home/theme/current"
default_id=nord

out_waybar="$config_home/waybar/theme.css"
out_rofi="$data_home/rofi/themes/theme-colors.rasi"
out_dunst="$config_home/dunst/dunstrc.d/90-theme.conf"
out_alacritty="$config_home/alacritty/theme.toml"
out_hypr="$config_home/hypr/state/theme.lua"
out_helix="$config_home/helix/themes/current.toml"
out_btop="$config_home/btop/themes/current.theme"
out_hyprlock="$config_home/hypr/state/hyprlock-colors.conf"
out_gtk3="$config_home/gtk-3.0/theme.css"
out_gtk4="$config_home/gtk-4.0/theme.css"

colour_keys="BG BG_ALT BG_SEL LINE FG FG_SOFT FG_BRIGHT MUTED ACCENT CRIT_FG
RED ORANGE YELLOW GREEN OK CYAN BLUE PURPLE TEAL
ANSI0 ANSI1 ANSI2 ANSI3 ANSI4 ANSI5 ANSI6 ANSI7
ANSI8 ANSI9 ANSI10 ANSI11 ANSI12 ANSI13 ANSI14 ANSI15"

# Not a colour: the name of one of helix's own themes (see the palettes).
name_keys="HELIX"

die() { printf 'theme.sh: %s\n' "$*" >&2; exit 1; }

valid_id() {
    case "$1" in
    '' | *[!a-z0-9-]*) return 1 ;;
    esac
    [ -f "$themes_dir/$1" ]
}

saved_id() {
    id=$(cat "$choice_file" 2>/dev/null || true)
    if valid_id "$id"; then
        printf '%s\n' "$id"
    else
        printf '%s\n' "$default_id"
    fi
}

# Source a palette into this shell, after checking it. The values land in CSS,
# rasi, TOML, Lua, btop's theme format, hyprlang and GTK CSS, so a typo must
# stop here and not become a parse error in nine programs.
load_palette() {
    valid_id "$1" || die "unknown theme: $1"
    for k in NAME $name_keys $colour_keys; do unset "$k"; done
    # shellcheck disable=SC1090
    . "$themes_dir/$1"
    [ -n "${NAME:-}" ] || die "$1: NAME is missing"
    for k in $colour_keys; do
        eval "v=\${$k:-}"
        case "$v" in
        '#'[0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f][0-9A-Fa-f]) ;;
        *) die "$1: $k is missing or not #rrggbb" ;;
        esac
    done
    # HELIX ends up in a TOML string, so it gets the same strictness as a
    # colour, just a different alphabet: helix theme names are file names.
    case "${HELIX:-}" in
    '' | *[!a-z0-9_-]*) die "$1: HELIX is missing or not [a-z0-9_-]+" ;;
    esac
}

# tmp + mv in the destination directory, so a program that re-reads on a file
# event never sees half a file.
write_atomic() {
    dest=$1
    mkdir -p "$(dirname "$dest")"
    tmp=$(mktemp "$(dirname "$dest")/.$(basename "$dest").XXXXXX")
    if cat >"$tmp" && chmod 644 "$tmp" && mv -f "$tmp" "$dest"; then
        return 0
    fi
    rm -f "$tmp"
    return 1
}

# Hyprland wants rgb(rrggbb): no hash.
bare() { printf '%s' "${1#\#}" | tr 'A-F' 'a-f'; }

render_waybar() {
    write_atomic "$out_waybar" <<EOT
/* generated by theme.sh — do not edit. Theme: $NAME */
@define-color bg $BG;
@define-color bg_alt $BG_ALT;
@define-color line $LINE;
@define-color fg $FG;
@define-color fg_soft $FG_SOFT;
@define-color fg_bright $FG_BRIGHT;
@define-color muted $MUTED;
@define-color accent $ACCENT;
@define-color red $RED;
@define-color orange $ORANGE;
@define-color yellow $YELLOW;
@define-color green $GREEN;
@define-color ok $OK;
@define-color cyan $CYAN;
@define-color blue $BLUE;
@define-color purple $PURPLE;
@define-color teal $TEAL;
EOT
}

render_rofi() {
    write_atomic "$out_rofi" <<EOT
/* generated by theme.sh — do not edit. Theme: $NAME */
* {
    bg:     $BG;
    bg-alt: $BG_ALT;
    line:   $LINE;
    fg:     $FG;
    muted:  $MUTED;
    accent: $ACCENT;
}
EOT
}

# Drop-in: dunst reads dunstrc.d/*.conf after dunstrc, so only colours go here.
render_dunst() {
    write_atomic "$out_dunst" <<EOT
# generated by theme.sh — do not edit. Theme: $NAME
[global]
    frame_color = "$LINE"
    highlight = "$ACCENT"

[urgency_low]
    background = "$BG"
    foreground = "$FG"
    frame_color = "$LINE"

[urgency_normal]
    background = "$BG"
    foreground = "$FG_SOFT"
    frame_color = "$LINE"

[urgency_critical]
    background = "$RED"
    foreground = "$CRIT_FG"
    frame_color = "$ORANGE"
EOT
}

# Imported by alacritty.toml. Cursor and selection are left out on purpose:
# alacritty then draws them by inverting the cell, which suits every palette.
render_alacritty() {
    write_atomic "$out_alacritty" <<EOT
# generated by theme.sh — do not edit. Theme: $NAME
[colors.primary]
background = "$BG"
foreground = "$FG"

[colors.normal]
black = "$ANSI0"
red = "$ANSI1"
green = "$ANSI2"
yellow = "$ANSI3"
blue = "$ANSI4"
magenta = "$ANSI5"
cyan = "$ANSI6"
white = "$ANSI7"

[colors.bright]
black = "$ANSI8"
red = "$ANSI9"
green = "$ANSI10"
yellow = "$ANSI11"
blue = "$ANSI12"
magenta = "$ANSI13"
cyan = "$ANSI14"
white = "$ANSI15"
EOT
}

render_hypr() {
    write_atomic "$out_hypr" <<EOT
-- generated by theme.sh — do not edit. Theme: $NAME
hl.config({
    general = {
        col = {
            active_border   = "rgb($(bare "$ACCENT"))",
            inactive_border = "rgb($(bare "$LINE"))",
        },
    },
})
hl.window_rule({
    name  = "dropdown-border",
    match = { class = "^(dropterm|drop-.+)$" },
    border_color = "rgb($(bare "$YELLOW"))",
})
EOT
}

# helix cannot take a palette, only a theme, so this one is a name: current.toml
# just inherits one of helix's built-in themes. config.toml says
# theme = "current". A running helix picks it up with :config-reload.
render_helix() {
    write_atomic "$out_helix" <<EOT
# generated by theme.sh — do not edit. Theme: $NAME
inherits = "$HELIX"
EOT
}

# btop does read colours, so this one is built from the palette. The keys and
# their order are btop's own (see /usr/share/btop/themes); each is given the
# palette role it had in the Nord theme this replaces. Gradients run start,
# mid, end. btop.conf says color_theme = "current", and btop finds the file in
# ~/.config/btop/themes. A running btop only reads it on restart.
render_btop() {
    write_atomic "$out_btop" <<EOT
# generated by theme.sh — do not edit. Theme: $NAME
theme[main_bg]="$BG"
theme[main_fg]="$FG"
theme[title]="$FG_BRIGHT"
theme[hi_fg]="$BLUE"
theme[selected_bg]="$LINE"
theme[selected_fg]="$ACCENT"
theme[inactive_fg]="$LINE"
theme[graph_text]="$FG"
theme[meter_bg]="$BG_ALT"
theme[proc_misc]="$ACCENT"
theme[cpu_box]="$BLUE"
theme[mem_box]="$GREEN"
theme[net_box]="$PURPLE"
theme[proc_box]="$TEAL"
theme[div_line]="$LINE"
theme[temp_start]="$GREEN"
theme[temp_mid]="$YELLOW"
theme[temp_end]="$RED"
theme[cpu_start]="$TEAL"
theme[cpu_mid]="$BLUE"
theme[cpu_end]="$PURPLE"
theme[free_start]="$GREEN"
theme[free_mid]="$TEAL"
theme[free_end]="$CYAN"
theme[cached_start]="$BLUE"
theme[cached_mid]="$BLUE"
theme[cached_end]="$PURPLE"
theme[available_start]="$YELLOW"
theme[available_mid]="$ORANGE"
theme[available_end]="$RED"
theme[used_start]="$GREEN"
theme[used_mid]="$YELLOW"
theme[used_end]="$RED"
theme[download_start]="$TEAL"
theme[download_mid]="$CYAN"
theme[download_end]="$BLUE"
theme[upload_start]="$PURPLE"
theme[upload_mid]="$ORANGE"
theme[upload_end]="$RED"
theme[process_start]="$TEAL"
theme[process_mid]="$BLUE"
theme[process_end]="$PURPLE"
EOT
}

# hyprlock is hyprlang, and hyprlock.conf sources this file. hyprlang wants
# rgba(rrggbbaa), and its variables are plain text substitution, so each one
# is the whole colour. Lowercase names, so they never meet hyprlock's own
# $TIME and friends. Read when hyprlock starts: there is nothing to reload.
render_hyprlock() {
    write_atomic "$out_hyprlock" <<EOT
# generated by theme.sh — do not edit. Theme: $NAME
\$fg = rgba($(bare "$FG")ff)
\$fg_bright = rgba($(bare "$FG_BRIGHT")ff)
\$accent = rgba($(bare "$ACCENT")ff)
\$red = rgba($(bare "$RED")ff)
EOT
}

# GTK. adw-gtk3 (GTK 3) and libadwaita (GTK 4) both take their colours from the
# libadwaita names, so the two files share this block and GTK 3 adds the older
# theme_* names on top. gtk.css in each directory is tracked and only imports
# the generated file. Light text on the accent and status colours is the
# palette's BG; on the two reds it is CRIT_FG, which each palette picks so the
# text reads on its red. The shades stay black at 20%: they darken, they do not
# colour. A running GTK app keeps its old colours until it is restarted.
gtk_colors() {
    cat <<EOT
@define-color window_bg_color $BG;
@define-color window_fg_color $FG;
@define-color view_bg_color $BG;
@define-color view_fg_color $FG;
@define-color headerbar_bg_color $BG_ALT;
@define-color headerbar_fg_color $FG;
@define-color headerbar_border_color $BG_SEL;
@define-color headerbar_backdrop_color $BG;
@define-color headerbar_shade_color rgba(0, 0, 0, 0.2);
@define-color card_bg_color $BG_ALT;
@define-color card_fg_color $FG;
@define-color card_shade_color rgba(0, 0, 0, 0.2);
@define-color popover_bg_color $BG_ALT;
@define-color popover_fg_color $FG;
@define-color dialog_bg_color $BG_ALT;
@define-color dialog_fg_color $FG;
@define-color sidebar_bg_color $BG_ALT;
@define-color sidebar_fg_color $FG;
@define-color sidebar_backdrop_color $BG;
@define-color sidebar_border_color $BG_SEL;
@define-color sidebar_shade_color rgba(0, 0, 0, 0.2);
@define-color accent_bg_color $ACCENT;
@define-color accent_fg_color $BG;
@define-color accent_color $ACCENT;
@define-color destructive_bg_color $RED;
@define-color destructive_fg_color $CRIT_FG;
@define-color destructive_color $RED;
@define-color success_bg_color $GREEN;
@define-color success_fg_color $BG;
@define-color success_color $GREEN;
@define-color warning_bg_color $YELLOW;
@define-color warning_fg_color $BG;
@define-color warning_color $YELLOW;
@define-color error_bg_color $RED;
@define-color error_fg_color $CRIT_FG;
@define-color error_color $RED;
EOT
}

render_gtk3() {
    {
        printf '/* generated by theme.sh — do not edit. Theme: %s */\n' "$NAME"
        gtk_colors
        cat <<EOT
@define-color theme_bg_color $BG;
@define-color theme_fg_color $FG;
@define-color theme_base_color $BG;
@define-color theme_text_color $FG;
@define-color theme_selected_bg_color $ACCENT;
@define-color theme_selected_fg_color $BG;
@define-color theme_unfocused_bg_color $BG;
@define-color theme_unfocused_fg_color $FG;
@define-color theme_unfocused_base_color $BG;
@define-color theme_unfocused_text_color $FG;
@define-color theme_unfocused_selected_bg_color $BG_SEL;
@define-color theme_unfocused_selected_fg_color $FG;
@define-color insensitive_bg_color $BG_ALT;
@define-color insensitive_fg_color $MUTED;
@define-color insensitive_base_color $BG;
@define-color borders $BG_SEL;
@define-color unfocused_borders $BG_ALT;
@define-color content_view_bg $BG;
@define-color tooltip_bg_color $BG_ALT;
@define-color tooltip_fg_color $FG;
@define-color tooltip_border_color $LINE;
EOT
    } | write_atomic "$out_gtk3"
}

render_gtk4() {
    {
        printf '/* generated by theme.sh — do not edit. Theme: %s */\n' "$NAME"
        gtk_colors
    } | write_atomic "$out_gtk4"
}

render() {
    load_palette "$1"
    render_waybar
    render_rofi
    render_dunst
    render_alacritty
    render_hypr
    render_helix
    render_btop
    render_hyprlock
    render_gtk3
    render_gtk4
}

# Every reload is allowed to fail: the program may simply not be running.
# alacritty is not here — live_config_reload watches its imports itself — and
# neither is rofi, which reads the theme on every run. helix and btop are not
# either: they read their theme on start (helix also on :config-reload), and
# reaching into a running editor is not this script's business. hyprlock reads
# its colours each time it starts, and GTK apps only when they start.
reload() {
    pkill -USR2 -x waybar >/dev/null 2>&1 || true
    dunstctl reload >/dev/null 2>&1 || true
    if [ -n "${HYPRLAND_INSTANCE_SIGNATURE:-}" ]; then
        hyprctl reload >/dev/null 2>&1 || true
    fi
}

# A generated file is stale when it is missing, or older than this script or
# the chosen palette: a new colour or a new rule (an OK green, a dropdown
# frame) reaches a machine only by re-rendering, and a config that names a
# colour the old file lacks (waybar's @ok) breaks. Re-rendering keeps the
# saved choice, so it never changes a theme someone picked.
stale() {
    palette="$themes_dir/$(saved_id)"
    for f in "$out_waybar" "$out_rofi" "$out_dunst" "$out_alacritty" "$out_hypr" \
        "$out_helix" "$out_btop" "$out_hyprlock" "$out_gtk3" "$out_gtk4"; do
        [ -f "$f" ] || return 0
        [ "$0" -nt "$f" ] && return 0
        [ "$palette" -nt "$f" ] && return 0
    done
    return 1
}

case "${1:-}" in
list)
    for f in "$themes_dir"/*; do
        [ -f "$f" ] || continue
        ( load_palette "${f##*/}" && printf '%s\t%s\n' "${f##*/}" "$NAME" )
    done
    ;;
current)
    saved_id
    ;;
set)
    [ $# -eq 2 ] || die "usage: theme.sh set <id>"
    load_palette "$2"
    printf '%s\n' "$2" | write_atomic "$choice_file"
    render "$2"
    reload
    ;;
apply)
    render "$(saved_id)"
    reload
    ;;
ensure)
    # Says what it did, so a caller (Ansible) can tell rendering from a no-op.
    if stale; then
        render "$(saved_id)"
        printf 'rendered %s\n' "$(saved_id)"
    fi
    ;;
*)
    die "usage: theme.sh list | current | set <id> | apply | ensure"
    ;;
esac
